{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"LA Just Cause for Eviction Ordinance (JCO)","requirement":"A landlord may end a tenancy only for a listed just cause and must pay relocation assistance for no-fault evictions such as owner move-in, demolition, conversion or government order to vacate.","key_value":null,"coverage_conditions":"Most residential properties in the City of Los Angeles not regulated by the City's Rent Stabilization Ordinance; applies once the tenant has lived in the unit six months or the original lease expired, whichever comes first.","applicability":{"built_on_or_before":null,"built_after":"1978-10-01","date_basis":"unspecified","min_units":null,"max_units":null,"owner_dependent":true,"other":"May apply to buildings newer than October 1, 1978 and to a property with only one single-family dwelling"},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner's roommate, cooperatives under certain circumstances, some non-profit facilities for the homeless or short-term substance abuse treatment centers, and some properties owned by HACLA or the government.","penalty":null,"effective_date":null,"citation":"Just Cause For Eviction Ordinance (JCO)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Non-payment eviction threshold tied to Fair Market Rent","requirement":"For RSO and JCO units, a landlord may not evict a tenant who falls behind in rent unless the amount owed is higher than the Fair Market Rent for that unit's bedroom size.","key_value":"Rent owed must exceed Fair Market Rent (by bedroom size)","coverage_conditions":"All RSO and JCO rental units in the City of Los Angeles.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All RSO and JCO rental units"},"exemptions":null,"penalty":null,"effective_date":"2023-03-27","citation":"Just Cause For Eviction Ordinance (JCO) – Evictions for Non-Payment of Rent","quoted_span":"Effective March 27, 2023, landlords may not evict a tenant who falls behind in rent unless the tenant owes an amount higher than the Fair Market Rent (FMR).","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Filing of eviction notices with LAHD","requirement":"Every eviction notice served on a tenant in the City of Los Angeles must be filed with LAHD within three business days of service on the tenant.","key_value":"3 business days","coverage_conditions":"All JCO and RSO rental properties in the City of Los Angeles.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All JCO and RSO rental properties"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Just Cause For Eviction Ordinance (JCO) – Eviction Notices Filed with LAHD","quoted_span":"All eviction notices issued to tenants in the City of Los Angeles must be filed with LAHD within three (3) business days of service on the tenant.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act (AB 1482) annual rent cap","requirement":"For covered units, annual rent increases may not exceed 5% plus the regional cost-of-living change, or 10%, whichever is lower; the maximum allowable increase was 8.9% from August 1, 2024 to July 31, 2025.","key_value":"5% + CPI, max 10%; 8.9% for 8/1/2024–7/31/2025","coverage_conditions":"Units more than 15 years old on a rolling basis that are not subject to the City's RSO; single-family homes and condominiums covered only if not owned by a trust, corporation or LLC with a corporate member and the tenant received written notice.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":true,"other":"Rolling 15-year construction cutoff; ownership and written-notice conditions for single-family homes and condominiums"},"exemptions":"Units constructed within the last 15 years; units restricted by deed or recorded document to low- or moderate-income households; certain dormitories; a two-unit property where the owner occupied the second unit for the entire tenancy; qualifying single-family homes and condominiums; RSO units.","penalty":null,"effective_date":"2024-08-01","citation":"Cal. Civ. Code § 1947.12","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%","interaction":"The City's JCO does not regulate rent increases; AB 1482 may regulate rents in buildings older than 15 years.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
